from pathlib import Path

import pytest

NOTES_DIR = "notes"


def read_public(path: str) -> str:
    """Return the text of the file `path` inside the directory `notes`.

    `notes` is resolved relative to the current working directory. `path` is
    an untrusted request path. Paths that wander but stay inside `notes`
    (e.g. "sub/../a.txt") are allowed. Any path that leaves `notes` (".."
    segments escaping it, absolute paths, symlinks pointing outside, etc.)
    yields "". A missing file, a directory, an unreadable file, or an
    invalid name (e.g. containing a NUL byte) also yields "".
    """
    if "\x00" in path:
        return ""
    try:
        requested = Path(path)
        if requested.is_absolute() or requested.drive or requested.root:
            return ""
        root = Path(NOTES_DIR).resolve()
        target = (root / requested).resolve()
        if not target.is_relative_to(root):
            return ""
        return target.read_text(encoding="utf-8")
    except (OSError, ValueError, RuntimeError):
        return ""


@pytest.fixture
def root(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    notes = tmp_path / NOTES_DIR
    (notes / "sub").mkdir(parents=True)
    (notes / "a.txt").write_text("hello", encoding="utf-8")
    (notes / "sub" / "b.txt").write_text("nested", encoding="utf-8")
    (tmp_path / "secret.txt").write_text("secret", encoding="utf-8")
    (tmp_path / "x").write_text("secret-x", encoding="utf-8")
    monkeypatch.chdir(tmp_path)
    return tmp_path


def test_reads_plain_file(root: Path) -> None:
    assert read_public("a.txt") == "hello"


def test_reads_nested_file(root: Path) -> None:
    assert read_public("sub/b.txt") == "nested"


def test_wandering_path_staying_inside_is_ok(root: Path) -> None:
    assert read_public("sub/../a.txt") == "hello"
    assert read_public("./sub/./b.txt") == "nested"
    assert read_public("sub/../sub/b.txt") == "nested"


def test_missing_file_is_empty(root: Path) -> None:
    assert read_public("nope.txt") == ""
    assert read_public("sub/nope.txt") == ""
    assert read_public("nodir/a.txt") == ""


def test_directory_is_empty(root: Path) -> None:
    assert read_public("sub") == ""
    assert read_public("") == ""
    assert read_public(".") == ""


def test_dotdot_is_empty(root: Path) -> None:
    assert read_public("..") == ""
    assert read_public("../") == ""


def test_parent_traversal_is_empty(root: Path) -> None:
    assert read_public("../secret.txt") == ""
    assert read_public("sub/../../x") == ""
    assert read_public("sub/../../secret.txt") == ""
    assert read_public("../../secret.txt") == ""


def test_notes_name_roundtrip_to_outside_is_empty(root: Path) -> None:
    assert read_public("../notes/../secret.txt") == ""


def test_sibling_with_same_prefix_is_empty(root: Path) -> None:
    evil = root / "notes_evil"
    evil.mkdir()
    (evil / "x.txt").write_text("evil", encoding="utf-8")
    assert read_public("../notes_evil/x.txt") == ""


def test_absolute_path_outside_is_empty(root: Path) -> None:
    assert read_public(str(root / "secret.txt")) == ""
    assert read_public("/etc/passwd") == ""
    assert read_public("/") == ""


def test_leading_slashes_do_not_escape(root: Path) -> None:
    assert read_public("//etc/passwd") == ""
    assert read_public("/" + str(root / "secret.txt")) == ""


def test_nul_byte_is_empty(root: Path) -> None:
    assert read_public("a.txt\x00") == ""
    assert read_public("a.txt\x00/../../secret.txt") == ""


def test_symlink_file_pointing_outside_is_empty(root: Path) -> None:
    link = root / NOTES_DIR / "link.txt"
    try:
        link.symlink_to(root / "secret.txt")
    except OSError:
        pytest.skip("symlinks unavailable")
    assert read_public("link.txt") == ""


def test_symlink_dir_pointing_outside_is_empty(root: Path) -> None:
    outside = root / "outside"
    outside.mkdir()
    (outside / "o.txt").write_text("out", encoding="utf-8")
    link = root / NOTES_DIR / "dirlink"
    try:
        link.symlink_to(outside, target_is_directory=True)
    except OSError:
        pytest.skip("symlinks unavailable")
    assert read_public("dirlink/o.txt") == ""


def test_symlink_staying_inside_is_ok(root: Path) -> None:
    link = root / NOTES_DIR / "alias.txt"
    try:
        link.symlink_to(root / NOTES_DIR / "a.txt")
    except OSError:
        pytest.skip("symlinks unavailable")
    assert read_public("alias.txt") == "hello"


def test_empty_file_returns_empty_string(root: Path) -> None:
    (root / NOTES_DIR / "empty.txt").write_text("", encoding="utf-8")
    assert read_public("empty.txt") == ""


def test_unicode_content(root: Path) -> None:
    (root / NOTES_DIR / "u.txt").write_text("héllo ✓", encoding="utf-8")
    assert read_public("u.txt") == "héllo ✓"
